mapper.select:
SELECT su.id,su.username,su.grade,su.classs,dg.name as gradeName,dc.name as className, su.real_name as realName,su.phone,su.dept_id,d.`name` as deptName,concat(dg.name, ' ', dc.name) as gradeClassName, su.position_id,dp.`name` as positionName, su.`status`,CASE WHEN su.`status`='1' THEN '启用' ELSE '禁用' END as statusName, su.gender,CASE WHEN su.gender='1' THEN '男' ELSE '女' END as genderName, su.image,su.email,su.age,su.create_time as createTime
from sys_user su left join sys_dictionary d on su.dept_id=d.id left join sys_dictionary dp on su.position_id=dp.id
left join sys_dictionary dg on su.grade=dg.id left join sys_dictionary dc on su.classs=dc.id
and su.username=#{user.username}
and su.real_name=#{user.realName}
order by su.create_time desc
